begin;
create schema if not exists extensions;
create extension if not exists pgcrypto with schema extensions;
create table public.profiles(id uuid primary key references auth.users on delete cascade, display_name text not null check(length(display_name) between 1 and 80), created_at timestamptz not null default now());
create table public.households(id uuid primary key default gen_random_uuid(), name text not null check(length(name) between 1 and 120), created_at timestamptz not null default now());
create table public.household_members(household_id uuid references public.households on delete cascade, user_id uuid references public.profiles on delete cascade, primary key(household_id,user_id));
create function public.is_member(h uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from household_members where household_id=h and user_id=auth.uid())$$;
create table public.household_invitations(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households on delete cascade,email text not null, token_hash text not null unique,expires_at timestamptz not null default now()+interval '7 days',accepted_at timestamptz,created_at timestamptz not null default now());
create table public.rooms(id uuid primary key default gen_random_uuid(), household_id uuid not null references public.households on delete cascade, title text not null, description text not null default '', image_url text, width_cm integer check(width_cm>0),length_cm integer check(length_cm>0),paint text not null default '',materials text not null default '',sort_order integer not null default 0,status text not null default 'Actief' check(status in ('Actief','Gearchiveerd')),created_by uuid default auth.uid() references public.profiles,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),version integer not null default 1,unique(id,household_id));
create table public.projects(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households on delete cascade,title text not null,description text not null default '',room_id uuid, image_url text,status text not null default 'Idee' check(status in ('Idee','Gepland','In uitvoering','Gepauzeerd','Afgerond')),start_date date,due_date date,budget_cents bigint not null default 0 check(budget_cents>=0),created_by uuid default auth.uid() references public.profiles,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),version integer not null default 1,unique(id,household_id),foreign key(room_id,household_id) references public.rooms(id,household_id));
create table public.ideas(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households on delete cascade,title text not null,description text not null default '',room_id uuid,project_id uuid,image_url text,url text,tags text[] not null default '{}',favorite boolean not null default false,cost_cents bigint not null default 0 check(cost_cents>=0),status text not null default 'Nieuw' check(status in ('Nieuw','Bespreken','Goedgekeurd','Voor later','Afgewezen','Uitgevoerd')),created_by uuid default auth.uid() references public.profiles,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),version integer not null default 1,unique(id,household_id),foreign key(room_id,household_id) references public.rooms(id,household_id),foreign key(project_id,household_id) references public.projects(id,household_id));
create table public.tasks(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households on delete cascade,title text not null,description text not null default '',room_id uuid,project_id uuid,assignee_id uuid,priority text not null default 'Normaal' check(priority in ('Laag','Normaal','Hoog','Urgent')),status text not null default 'Te doen' check(status in ('Te doen','Bezig','Geblokkeerd','Afgerond')),due_date date,duration_minutes integer check(duration_minutes>=0),created_by uuid default auth.uid() references public.profiles,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),version integer not null default 1,unique(id,household_id),foreign key(room_id,household_id) references public.rooms(id,household_id),foreign key(project_id,household_id) references public.projects(id,household_id),foreign key(household_id,assignee_id) references public.household_members(household_id,user_id));
create table public.expenses(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households on delete cascade,title text not null,description text not null default '',amount_cents bigint not null check(amount_cents>0 and amount_cents<=100000000),expense_date date not null,category text not null,room_id uuid,project_id uuid,idempotency_key uuid not null unique,created_by uuid default auth.uid() references public.profiles,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),version integer not null default 1,unique(id,household_id),foreign key(room_id,household_id) references public.rooms(id,household_id),foreign key(project_id,household_id) references public.projects(id,household_id));
create table public.expense_payments(id uuid primary key default gen_random_uuid(),household_id uuid not null,expense_id uuid not null,user_id uuid not null,amount_cents bigint not null check(amount_cents>=0),unique(expense_id,user_id),foreign key(expense_id,household_id) references public.expenses(id,household_id),foreign key(household_id,user_id) references public.household_members(household_id,user_id));
create table public.expense_shares(like public.expense_payments including defaults including constraints including indexes);
alter table public.expense_shares add foreign key(expense_id,household_id) references public.expenses(id,household_id),add foreign key(household_id,user_id) references public.household_members(household_id,user_id);
create table public.settlements(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households,from_user uuid not null,to_user uuid not null,amount_cents bigint not null check(amount_cents>0),reversed_at timestamptz,idempotency_key uuid not null unique,created_at timestamptz not null default now(),check(from_user<>to_user),foreign key(household_id,from_user) references public.household_members(household_id,user_id),foreign key(household_id,to_user) references public.household_members(household_id,user_id));
create table public.budgets(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households,title text not null,room_id uuid,project_id uuid,amount_cents bigint not null check(amount_cents>=0),created_by uuid default auth.uid() references public.profiles,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),version integer not null default 1,foreign key(room_id,household_id) references public.rooms(id,household_id),foreign key(project_id,household_id) references public.projects(id,household_id));
create table public.savings_goals(like public.budgets including defaults including constraints including indexes);
alter table public.savings_goals add column saved_cents bigint not null default 0 check(saved_cents>=0),add foreign key(household_id) references public.households,add foreign key(room_id,household_id) references public.rooms(id,household_id),add foreign key(project_id,household_id) references public.projects(id,household_id);
create table public.wishlist_items(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households,title text not null,description text not null default '',room_id uuid,project_id uuid,image_url text,url text,store text not null default '',price_cents bigint not null default 0 check(price_cents>=0),quantity integer not null default 1 check(quantity>0),priority text not null default 'Normaal',due_date date,status text not null default 'Gewenst' check(status in ('Gewenst','Vergelijken','Goedgekeurd','Besteld','Geleverd','Gekocht','Geannuleerd')),expense_id uuid,created_by uuid default auth.uid() references public.profiles,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),version integer not null default 1,unique(id,household_id),foreign key(room_id,household_id) references public.rooms(id,household_id),foreign key(project_id,household_id) references public.projects(id,household_id),foreign key(expense_id,household_id) references public.expenses(id,household_id));
create table public.calendar_events(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households,title text not null,description text not null default '',room_id uuid,project_id uuid,task_id uuid,starts_at timestamptz not null,ends_at timestamptz not null,category text not null default 'Klusdag',created_by uuid default auth.uid() references public.profiles,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),version integer not null default 1,check(ends_at>starts_at),foreign key(room_id,household_id) references public.rooms(id,household_id),foreign key(project_id,household_id) references public.projects(id,household_id),foreign key(task_id,household_id) references public.tasks(id,household_id));
create table public.maintenance_items(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households,title text not null,description text not null default '',room_id uuid,assignee_id uuid,category text not null default 'Algemeen',frequency_months integer not null default 12 check(frequency_months between 1 and 120),last_done date,due_date date not null,cost_cents bigint not null default 0 check(cost_cents>=0),created_by uuid default auth.uid() references public.profiles,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),version integer not null default 1,unique(id,household_id),foreign key(room_id,household_id) references public.rooms(id,household_id),foreign key(household_id,assignee_id) references public.household_members(household_id,user_id));
create table public.documents(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households,title text not null,description text not null default '',room_id uuid,project_id uuid,category text not null default 'Document',storage_path text not null,filename text not null,mime_type text not null,bytes bigint not null check(bytes between 1 and 10485760),created_by uuid default auth.uid() references public.profiles,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),version integer not null default 1,foreign key(room_id,household_id) references public.rooms(id,household_id),foreign key(project_id,household_id) references public.projects(id,household_id));
create table public.activity_log(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households,user_id uuid default auth.uid() references public.profiles,entity text not null,entity_id uuid,action text not null,title text,created_at timestamptz not null default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households,user_id uuid not null,title text not null,read_at timestamptz,created_at timestamptz not null default now(),foreign key(household_id,user_id) references public.household_members(household_id,user_id));
-- Dependent records carry a household identifier and composite foreign keys; no cross-household links.
create table public.room_photos(id uuid primary key default gen_random_uuid(),household_id uuid not null,room_id uuid not null,storage_path text not null,caption text not null default '',created_at timestamptz not null default now(),foreign key(room_id,household_id) references public.rooms(id,household_id));
create table public.idea_photos(id uuid primary key default gen_random_uuid(),household_id uuid not null,idea_id uuid not null,storage_path text not null,created_at timestamptz not null default now(),foreign key(idea_id,household_id) references public.ideas(id,household_id));
create table public.idea_comments(id uuid primary key default gen_random_uuid(),household_id uuid not null,idea_id uuid not null,body text not null check(length(body) between 1 and 4000),user_id uuid not null default auth.uid(),created_at timestamptz not null default now(),foreign key(idea_id,household_id) references public.ideas(id,household_id),foreign key(household_id,user_id) references public.household_members(household_id,user_id));
create table public.task_subtasks(id uuid primary key default gen_random_uuid(),household_id uuid not null,task_id uuid not null,title text not null,done boolean not null default false,created_at timestamptz not null default now(),foreign key(task_id,household_id) references public.tasks(id,household_id));
create table public.task_assignees(household_id uuid not null,task_id uuid not null,user_id uuid not null,primary key(task_id,user_id),foreign key(task_id,household_id) references public.tasks(id,household_id),foreign key(household_id,user_id) references public.household_members(household_id,user_id));
create table public.project_phases(id uuid primary key default gen_random_uuid(),household_id uuid not null,project_id uuid not null,title text not null,done boolean not null default false,sort_order integer not null default 0,created_at timestamptz not null default now(),foreign key(project_id,household_id) references public.projects(id,household_id));
create table public.maintenance_history(id uuid primary key default gen_random_uuid(),household_id uuid not null,maintenance_id uuid not null,performed_on date not null,cost_cents bigint not null default 0 check(cost_cents>=0),user_id uuid not null default auth.uid(),created_at timestamptz not null default now(),foreign key(maintenance_id,household_id) references public.maintenance_items(id,household_id),foreign key(household_id,user_id) references public.household_members(household_id,user_id));
create table public.settlement_allocations(household_id uuid not null,settlement_id uuid not null references public.settlements,expense_id uuid not null,amount_cents bigint not null check(amount_cents>0),primary key(settlement_id,expense_id),foreign key(expense_id,household_id) references public.expenses(id,household_id));
-- Profile visibility is limited to oneself and co-members.
alter table public.profiles enable row level security;
create policy profiles_read on public.profiles for select to authenticated using(id=auth.uid() or exists(select 1 from public.household_members m join public.household_members mine on mine.household_id=m.household_id where m.user_id=id and mine.user_id=auth.uid()));
create policy profiles_update on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
alter table public.households enable row level security;
create policy households_read on public.households for select to authenticated using(public.is_member(id));
alter table public.household_members enable row level security;
create policy members_read on public.household_members for select to authenticated using(public.is_member(household_id));
do $$ declare t text; begin
 for t in select tablename from pg_tables where schemaname='public' and tablename not in ('profiles','households','household_members') loop
  execute format('alter table public.%I enable row level security',t);
  execute format('create policy member_read on public.%I for select to authenticated using(public.is_member(household_id))',t);
  execute format('create index on public.%I(household_id)',t);
  if t not in ('household_invitations','expenses','expense_payments','expense_shares','settlements','settlement_allocations','activity_log','maintenance_history') then
   execute format('create policy member_insert on public.%I for insert to authenticated with check(public.is_member(household_id))',t);
   execute format('create policy member_update on public.%I for update to authenticated using(public.is_member(household_id)) with check(public.is_member(household_id))',t);
   execute format('create policy member_delete on public.%I for delete to authenticated using(public.is_member(household_id))',t);
  end if;
 end loop;
end $$;
-- All versioned writes get an immutable tenant and an audit record.
create function public.version_record() returns trigger language plpgsql set search_path=public as $$begin
 if new.household_id<>old.household_id or new.created_by is distinct from old.created_by then raise exception 'Onveranderlijke eigenaar'; end if;
 new.updated_at=now();new.version=old.version+1;return new;end$$;
create function public.audit_record() returns trigger language plpgsql security definer set search_path=public as $$begin
 insert into activity_log(household_id,entity,entity_id,action,title) values(coalesce(new.household_id,old.household_id),tg_table_name,coalesce(new.id,old.id),tg_op,coalesce(new.title,old.title));return null;end$$;
do $$ declare t text; begin for t in select table_name from information_schema.columns where table_schema='public' and column_name='version' loop
 execute format('create trigger version_update before update on public.%I for each row execute function public.version_record()',t);
 execute format('create trigger audit_change after insert or update or delete on public.%I for each row execute function public.audit_record()',t);
 end loop;end$$;
create function public.create_household(house_name text,person_name text) returns uuid language plpgsql security definer set search_path=public as $$declare h uuid;begin
 if auth.uid() is null then raise exception 'Log eerst in';end if;
 if exists(select 1 from household_members where user_id=auth.uid()) then raise exception 'Je hebt al een huishouden';end if;
 insert into profiles(id,display_name) values(auth.uid(),person_name) on conflict(id) do update set display_name=excluded.display_name;
 insert into households(name) values(house_name) returning id into h;insert into household_members values(h,auth.uid());return h;end$$;
create function public.create_invitation(h uuid,invite_email text) returns text language plpgsql security definer set search_path=public as $$declare token text=encode(extensions.gen_random_bytes(32),'hex');begin
 if not is_member(h) then raise exception 'Geen toegang';end if;
 insert into household_invitations(household_id,email,token_hash) values(h,lower(trim(invite_email)),encode(extensions.digest(token,'sha256'),'hex'));return token;end$$;
create function public.accept_invitation(token text,person_name text) returns uuid language plpgsql security definer set search_path=public as $$declare inv household_invitations;begin
 if auth.uid() is null then raise exception 'Log eerst in';end if;
 select * into inv from household_invitations where token_hash=encode(extensions.digest(token,'sha256'),'hex') for update;
 if inv.id is null or inv.accepted_at is not null or inv.expires_at<now() or lower(inv.email)<>lower(auth.jwt()->>'email') then raise exception 'Uitnodiging ongeldig, verlopen of voor een ander e-mailadres';end if;
 insert into profiles(id,display_name) values(auth.uid(),person_name) on conflict(id) do nothing;
 insert into household_members values(inv.household_id,auth.uid()) on conflict do nothing;update household_invitations set accepted_at=now() where id=inv.id;return inv.household_id;end$$;
-- Realtime uses exactly the same RLS read policies.
do $$declare t text;begin for t in select tablename from pg_tables where schemaname='public' and tablename not in ('household_invitations') loop
 execute format('alter publication supabase_realtime add table public.%I',t);
 end loop;end$$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('home-files','home-files',false,10485760,array['image/jpeg','image/png','image/webp','application/pdf']) on conflict(id) do nothing;
create policy private_files_read on storage.objects for select to authenticated using(bucket_id='home-files' and public.is_member((storage.foldername(name))[1]::uuid));
create policy private_files_insert on storage.objects for insert to authenticated with check(bucket_id='home-files' and public.is_member((storage.foldername(name))[1]::uuid));
create policy private_files_delete on storage.objects for delete to authenticated using(bucket_id='home-files' and public.is_member((storage.foldername(name))[1]::uuid));
commit;
